def url(lang,path=''):
    return SITE+'/'+('en/' if lang=='en' else '')+path

def safe_json(value):
    return json.dumps(value,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')

def metadata(lang,path='',title=None,description=None):
    title,description=(title,description) if title else HOME[lang]
    canonical=url(lang,path)
    graph=[
      {'@type':'Organization','@id':SITE+'/#project','name':'Freedom GPT','url':SITE+'/', 'logo':SITE+'/media/site/project-cover.png','sameAs':[REPO,PROJECT['support']['telegram']]},
      {'@type':'WebSite','@id':SITE+'/#website','name':'Freedom GPT','url':SITE+'/','inLanguage':['ru','en'],'publisher':{'@id':SITE+'/#project'}},
      {'@type':'WebPage','@id':canonical+'#webpage','url':canonical,'name':title,'description':description,'inLanguage':lang,'isPartOf':{'@id':SITE+'/#website'},'dateModified':CONTENT_DATE,'about':{'@id':SITE+'/#application'}},
    ]
    if not path:
        graph += [
          {'@type':'SoftwareApplication','@id':SITE+'/#application','name':'Freedom GPT','url':SITE+'/','description':description,'applicationCategory':'DeveloperApplication','operatingSystem':'Windows 10/11 x64; Ubuntu 24.04 x64; macOS 26.2+ Apple Silicon preview','softwareVersion':VERSION,'isAccessibleForFree':True,'license':REPO+'/blob/main/LICENSE','offers':{'@type':'Offer','price':'0','priceCurrency':'USD','url':canonical+'#download'},'downloadUrl':REPO+'/releases/tag/v'+VERSION,'softwareHelp':url(lang,'install/windows/'),'publisher':{'@id':SITE+'/#project'},'featureList':(['Локальный чат','Помощь в программировании','Генерация изображений с отдельной моделью','Сохранённые проекты','Выбор моделей'] if lang=='ru' else ['Local chat','Coding assistance','Image generation with a separate model','Saved projects','Model selection'])},
          {'@type':'SoftwareSourceCode','@id':SITE+'/#source','name':'Freedom GPT source code','codeRepository':REPO,'license':REPO+'/blob/main/LICENSE','programmingLanguage':['Python','JavaScript'],'targetProduct':{'@id':SITE+'/#application'}},
        ]
    else:
        graph.append({'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Freedom GPT','item':url(lang)},{'@type':'ListItem','position':2,'name':PAGES[path][lang][2],'item':canonical}]})
    tags=f'''<title>{html.escape(title)}</title>
<meta name="description" content="{html.escape(description,quote=True)}">
<meta name="robots" content="index,follow,max-image-preview:large,max-snippet:-1,max-video-preview:-1">
<link rel="canonical" href="{canonical}">
<link rel="alternate" hreflang="ru" href="{url('ru',path)}"><link rel="alternate" hreflang="en" href="{url('en',path)}"><link rel="alternate" hreflang="x-default" href="{url('en',path)}">
<meta property="og:site_name" content="Freedom GPT"><meta property="og:type" content="website"><meta property="og:url" content="{canonical}">
<meta property="og:title" content="{html.escape(title,quote=True)}"><meta property="og:description" content="{html.escape(description,quote=True)}">
<meta property="og:locale" content="{'ru_RU' if lang=='ru' else 'en_US'}"><meta property="og:locale:alternate" content="{'en_US' if lang=='ru' else 'ru_RU'}">
<meta property="og:image" content="{SITE}/media/site/project-cover.png"><meta property="og:image:alt" content="Freedom GPT — free local AI for Windows, Ubuntu and macOS">
<meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{html.escape(title,quote=True)}"><meta name="twitter:description" content="{html.escape(description,quote=True)}"><meta name="twitter:image" content="{SITE}/media/site/project-cover.png">
<script type="application/ld+json">{safe_json({'@context':'https://schema.org','@graph':graph})}</script>'''
    return tags

def resource_links(lang):
    return ''.join(f'<a href="{url(lang,path).removeprefix(SITE)}">{html.escape(info[lang][2])}<span aria-hidden="true"> ↗</span></a>' for path,info in PAGES.items())

def home_resources(lang):
    en=lang=='en'
    return f'''<section class="section wrap seo-resources" id="guides"><div class="eyebrow">{'LOCAL AI · NO SUBSCRIPTION' if en else 'ЛОКАЛЬНЫЙ ИИ · БЕЗ ПОДПИСКИ'}</div><h2>{'Free AI. A practical place to start.' if en else 'Бесплатные нейросети.<br>Понятно, с чего начать.'}</h2><p>{'Freedom GPT is a free application with MIT-licensed source code. Local inference does not require a paid API or a subscription. You provide the computer, disk space and electricity; model licenses are separate. Not every model fits every PC.' if en else 'Freedom GPT — бесплатное приложение с исходным кодом под MIT. Для локальных запросов не нужны подписка и платный API. Нужны ваш компьютер, место на диске и электричество; у моделей отдельные лицензии. Не каждая модель подходит любому ПК.'}</p><div class="resource-links">{resource_links(lang)}</div><div class="seo-evidence"><a href="{REPO}/blob/main/VERIFICATION.md">{'Read the published checks and known limits ↗' if en else 'Проверки проекта и известные ограничения ↗'}</a><a href="{REPO}/blob/main/LICENSE">MIT · {'source code license' if en else 'лицензия исходного кода'} ↗</a></div></section>'''

def p(text):return '<p>'+text+'</p>'
def section(title,body):return '<section><h2>'+title+'</h2>'+body+'</section>'
def ul(items):return '<ul>'+''.join('<li>'+item+'</li>' for item in items)+'</ul>'

def install_body(lang,path):
    en=lang=='en';target={'install/windows/':'windows-x64','install/ubuntu/':'ubuntu-x64','install/macos/':'macos-arm64'}[path]
    name={'windows-x64':f'FreedomGPT-Setup-{VERSION}.exe','ubuntu-x64':f'FreedomGPT-Setup-{VERSION}-Ubuntu-x64.run','macos-arm64':f'FreedomGPT-{VERSION}-macOS-AppleSilicon.zip'}[target]
    file=release_files(VERSION)[name]
    intro={
     'windows-x64':('Install a local AI workspace on Windows 10 or 11 x64. Python, Node.js and inference engines are included. You do not need to create an account or subscribe to run local models.' if en else 'Установите локальное пространство ИИ на Windows 10 или 11 x64. Python, Node.js и движки уже включены. Для локальной работы не нужно создавать аккаунт или оформлять подписку.'),
     'ubuntu-x64':('This build targets Ubuntu 24.04 x64. The installer includes its Python environment, Node.js and engines. GPU drivers are installed separately. A clean-container installation was checked; this does not verify every GPU and desktop configuration.' if en else 'Сборка рассчитана на Ubuntu 24.04 x64. В установщике есть среда Python, Node.js и движки. Видеодрайвер устанавливается отдельно. Установка проверена в чистом контейнере; это не подтверждает работу каждой видеокарты и конфигурации рабочего стола.'),
     'macos-arm64':('This is an experimental Apple Silicon build, requiring M1 or newer and macOS 26.2+. It does not support Intel Macs. The package is unsigned and not notarized; execution on a physical Mac has not been verified. Read these limits before downloading.' if en else 'Это экспериментальная сборка для Apple Silicon M1 и новее, требуется macOS 26.2+. Для Intel Mac она не подходит. Пакет без подписи и нотарификации; запуск на настоящем Mac ещё не проверен. Учитывайте эти ограничения перед загрузкой.'),
    }[target]
    os_name={'windows-x64':'Windows','ubuntu-x64':'Ubuntu','macos-arm64':'Mac'}[target]
    content=p(intro)+f'<div class="guide-download"><a class="button primary" href="{file["url"]}">{"Download for " if en else "Скачать для "}{os_name} ↓</a><small>{html.escape(name)} · {file["bytes"]/10**9:.2f} GB · GitHub</small></div>'
    content+=section('Installation steps' if en else 'Установка по шагам','<ol class="guide-steps">'+''.join('<li><strong>'+heading+'</strong>'+p(text.replace('macOS26.2','macOS 26.2').replace('above.','on this page.').replace('выше.','на этой странице.').replace('below.','in the block below.'))+'</li>' for heading,text in steps(target,en))+'</ol>')
    if target=='windows-x64':
        content+=section('EXE or ZIP?' if en else 'Что выбрать: EXE или ZIP?',p('EXE is the recommended graphical installer. ZIP is a portable folder: extract the entire archive into a new SSD folder and start FreedomGPT.exe. Copying only the EXE from the ZIP is not enough. Use a new installation folder; keep existing chats and model files.' if en else 'EXE — основной установщик с выбором языка и папки. ZIP — переносимая папка: полностью распакуйте архив на SSD и запустите FreedomGPT.exe. Одного EXE, вынутого из ZIP, недостаточно. Для новой установки выбирайте новую папку; сохраняйте существующие чаты и модели.'))
    elif target=='ubuntu-x64':
        content+=command_block('sh ./'+name,'launch-ubuntu','Ubuntu · '+('downloaded file' if en else 'скачанный файл'),en)
        content+=section('Other package formats' if en else 'Другие форматы пакетов',p('Choose .run for the guided installation. DEB is available for package-manager workflows; TAR.GZ is intended for manual installation. Run the desktop application as your normal user. Keep the installation and model folders on storage with enough free space.' if en else 'Выберите .run для обычной установки. DEB предназначен для установки пакетным менеджером, TAR.GZ — для ручного размещения. Само приложение запускайте от обычного пользователя. Для приложения и весов моделей понадобится свободное место на диске.'))
    else:
        content+=section('Before first launch' if en else 'Перед первым запуском',p('Unpack the complete app bundle. macOS may require approval through its standard security interface. This guide does not ask you to disable Gatekeeper or remove quarantine attributes. Native performance, image generation and video have not been validated on Mac.' if en else 'Распакуйте приложение целиком. macOS может запросить разрешение через штатный интерфейс безопасности. Инструкция не требует отключать Gatekeeper или удалять атрибут карантина. Производительность, генерация изображений и видео на Mac пока не подтверждены.'))
    intro2=('Paste the entire block in '+('PowerShell' if target=='windows-x64' else 'Terminal')+'. It downloads the official release with resume support and verifies SHA256 before launching. ' if en else 'Вставьте блок целиком в '+('PowerShell' if target=='windows-x64' else 'терминал')+'. Он скачает официальный релиз с поддержкой продолжения загрузки и проверит SHA256 перед запуском. ')
    if target=='windows-x64':intro2+=('Enter a new empty SSD folder outside your user profile when prompted. This creates a portable installation.' if en else 'При запросе укажите новую пустую папку на SSD вне папки пользователя. Будет создана переносимая установка.')
    if target=='ubuntu-x64':intro2+=('Requires curl. If it is unavailable, download the file with the button and run the short command above.' if en else 'Нужен curl. Если он отсутствует, скачайте файл кнопкой и выполните короткую команду выше.')
    if target=='macos-arm64':intro2+=('These commands have not been executed on a physical Mac.' if en else 'Эти команды ещё не выполнялись на настоящем Mac.')
    content+=section('Terminal installation' if en else 'Установка через терминал',p(intro2)+command_block(commands(target,VERSION,REPO),'install-command-'+target,('PowerShell' if target=='windows-x64' else 'Terminal'),en))
    content+=section('Choose a first model' if en else 'Выберите первую модель',p(('Model weights are separate from the installer. Let the application inspect RAM, VRAM and storage, then select a model that fits. Start with a small model on a low-memory PC. Downloading requires internet; local chat can work offline afterwards. ' if en else 'Веса моделей не входят в установщик. Дождитесь проверки RAM, VRAM и диска и выберите подходящую модель. На ПК с небольшой памятью начните с лёгкого варианта. Для загрузки нужен интернет; затем локальный чат может работать офлайн. ')+f'<a href="{url(lang,"guides/choose-model/").removeprefix(SITE)}">'+('Model sizes and memory guide' if en else 'Размеры моделей и требования к памяти')+'</a>.'))
    return content

def offline_body(lang):
    en=lang=='en'
    if en:
        return p('Freedom GPT is a free, open-source desktop workspace for running compatible AI models on your own hardware. Use one interface for chat, coding projects and files, and connect a separate image model for artwork. Local inference uses your computer rather than a paid cloud API.')+section('What is free?',ul(['The application is free to download and use. Its source code is published under the MIT license.','Local model requests have no subscription or per-token charge from Freedom GPT. Optional donations support development and do not unlock paid features.','You still provide storage, hardware, electricity and an internet connection for downloads. Each model has its own license. Check it before commercial use.']))+section('What works without internet?',p('Once the app and selected model files are installed, local conversations, code generation and compatible image generation can run offline. Keep model files on a connected drive. Web search, browsing external websites, downloading models and checking updates require network access.'))+section('Chat, code and images are different workloads',p('For coding, choose an instruction model and keep project files and clear requirements nearby. Test generated programs: a plausible answer is not evidence that code works. Image generation requires a dedicated generator, text encoder and VAE; a chat model alone does not render images. Video Studio is experimental and has only been verified on the published Windows RTX 4080 test configuration.'))+section('How to start',ul([f'<a href="{url("en","install/windows/").removeprefix(SITE)}">Install on Windows</a>, <a href="{url("en","install/ubuntu/").removeprefix(SITE)}">Ubuntu</a> or read the <a href="{url("en","install/macos/").removeprefix(SITE)}">Mac preview limitations</a>.','Let the installed application check memory and disk space. Choose and download a compatible model.','Activate the model and send a short request before starting a large project. Save files and project notes, rather than relying on an unlimited conversation.']))+section('Privacy and practical limits',p('Local inference is designed to keep your chat and model computation on the computer. It does not make every action offline: an agent can contact websites and external tools when you ask it to. Review the tools and integrations you enable. Keep backups of important work.'))+section('Is it the same as a commercial cloud assistant?',p('No. Freedom GPT does not provide free access to proprietary cloud models or copy a paid service’s capabilities. Quality depends on the open model, quantization, context and hardware you choose. Small models are easier to run but may struggle with long tasks and tool calls.'))
    return p('Freedom GPT — бесплатное приложение с открытым исходным кодом для запуска совместимых моделей на вашем железе. В одном интерфейсе доступны чат, проекты с кодом и файлы; для рисования подключается отдельная модель. Локальные запросы выполняет ваш компьютер, а не платный облачный API.')+section('Что именно бесплатно?',ul(['Приложение можно бесплатно скачать и использовать. Исходный код опубликован под лицензией MIT.','У локальных запросов нет подписки и оплаты за токены со стороны Freedom GPT. Добровольные донаты идут на развитие и не открывают платные функции.','Нужны ваш компьютер, электричество, место на диске и интернет для первоначальной загрузки. У каждой модели своя лицензия: проверьте её перед коммерческим использованием.']))+section('Что работает без интернета?',p('Когда приложение и нужные веса установлены, локальные диалоги, генерация кода и совместимая генерация изображений могут работать офлайн. Диск с моделями должен быть подключён. Поиск в сети, открытие внешних сайтов, скачивание моделей и проверка обновлений требуют интернета.'))+section('Чат, код и изображения — разные задачи',p('Для программирования выберите инструктивную модель, приложите требования и нужные файлы проекта. Проверяйте программы тестами: уверенный ответ не доказывает, что код работает. Для изображений нужен отдельный генератор, текстовый энкодер и VAE; обычная чат-модель сама картинки не рисует. Видеостудия экспериментальная, проверка выполнена только на опубликованной конфигурации Windows с RTX 4080.'))+section('Как начать',ul([f'<a href="/install/windows/">Установите сборку Windows</a>, <a href="/install/ubuntu/">Ubuntu</a> или изучите <a href="/install/macos/">ограничения тестовой сборки Mac</a>.','Дождитесь проверки памяти и диска в приложении. Выберите и скачайте подходящую модель.','Активируйте модель и отправьте короткий запрос. Для большого проекта сохраняйте файлы и заметки о задаче; не рассчитывайте на бесконечный контекст диалога.']))+section('Локальность и приватность',p('При локальном запуске расчёты модели и история чата находятся на компьютере. Это не означает, что любая функция работает без сети: по вашей задаче агент может обращаться к сайтам и внешним инструментам. Проверяйте подключаемые интеграции и сохраняйте резервные копии важной работы.'))+section('Это полный аналог платного облачного ассистента?',p('Нет. Freedom GPT не предоставляет бесплатный доступ к закрытым облачным моделям и не обещает повторять возможности платного сервиса. Качество зависит от выбранной открытой модели, квантования, контекста и железа. Маленькие модели легче запустить, но они могут хуже справляться с длинными задачами и вызовами инструментов.'))

def model_body(lang):
    en=lang=='en';catalog=json.loads((ROOT/'app/catalog.json').read_text(encoding='utf-8'))
    names={'huihui-qwen38-coder':'Huihui Qwen3.8 Coder 27B · IQ3_S3','qwen35-4b':'Qwen3.5 4B · Q4_K_M','qwen35-08b':'Qwen3.5 0.8B · Q4_K_M','qwen-image21':'Qwen Image 2.1 Turbo · Q5_K_M','wan21-t2v-13b':'Wan 2.1 T2V 1.3B · experimental' if en else 'Wan 2.1 T2V 1.3B · экспериментальная'}
    rows=''
    for model in catalog:
        if model['id'] not in names:continue
        files=model['files'];total=sum(file['bytes'] for file in files)
        source=files[0]['url'].split('/resolve/')[0]
        rows+=f'<tr><th scope="row">{names[model["id"]]}</th><td>{total/10**9:.2f} GB</td><td>{len(files)}</td><td><a href="{source}" rel="noopener noreferrer">Hugging Face ↗</a></td></tr>'
    table=f'<div class="guide-table"><table><caption>{"Model files in the v" if en else "Файлы моделей в каталоге v"}{VERSION}</caption><thead><tr><th>{"Model" if en else "Модель"}</th><th>{"Download total" if en else "Всего скачать"}</th><th>{"Files" if en else "Файлов"}</th><th>{"Publisher" if en else "Источник"}</th></tr></thead><tbody>{rows}</tbody></table></div>'
    if en:
        return p('Choose for the task and available memory, rather than the largest parameter count. The first-run hardware check estimates memory suitability; it is not a promise of speed or successful use of every feature. The table below uses exact file sizes from this release’s model catalog. GB means decimal gigabytes; runtime memory and temporary space are extra.')+table+section('RAM and VRAM have different roles',p('RAM is system memory; VRAM is memory on the graphics card. Model weights, the context cache and inference buffers all consume memory. A download fitting on disk does not mean it fits in VRAM. Partial CPU offload can let a model run, but may reduce speed. More RAM helps when capacity is the constraint; it does not automatically make a GPU-bound workload faster.'))+section('A practical starting point',ul(['A small 0.8B or 4B model is a reasonable first test on a low-memory computer. Expect more limited reasoning, coding and tool use.','The standard Huihui Coder configuration targets around 32 GB system RAM and 16 GB NVIDIA VRAM. Leave at least 35 GB SSD space for the app, model packs and headroom; larger contexts need additional memory.','Image generation uses the full three-file image pack. Switch between coding and image generation to avoid keeping both large workloads in VRAM. GPU support and drivers still matter.']))+section('What does quantization change?',p('GGUF quantization reduces weight size. Lower precision may allow a larger model to fit, with a possible quality cost. Q4 and IQ3 names are not interchangeable quality guarantees across models. Compare outputs on your own tasks and keep the publisher’s model card and license.'))+section('Context and tokens per second',p('A longer context consumes more memory and can slow processing. Saving project notes and summarizing history helps manage the window, but cannot guarantee that every detail is preserved. A published long coding test on Windows 11 with an RTX 4080 measured 100.85 tokens/s on its specific setup. It is not a promise for every PC or a full 65K conversation.'))+section('Images, photos and experimental video',p('Image generation and photo analysis require different compatible model components. Do not infer visual capability from the word “Coder”. Wan Video Studio is experimental: a Windows RTX 4080 test generated a 512×288, 33-frame, 20-step clip in 52.68 seconds including restoration of the coding model. Other hardware and operating systems remain unverified.'))+section('Sources and verification',p(f'File sizes and download hashes come from the <a href="{REPO}/blob/main/app/catalog.json">published catalog</a>. Read <a href="{REPO}/blob/main/VERIFICATION.md">verification notes and limits</a> before planning production work. Models are downloaded from their publishers and retain separate licenses.'))
    return p('Выбирайте модель под задачу и доступную память, а не только по числу параметров. Проверка ПК оценивает пригодность по памяти; она не гарантирует скорость и работу каждой функции. В таблице приведены точные размеры файлов из каталога этой версии. ГБ указаны в десятичной системе; память для расчётов и временное место нужны дополнительно.')+table+section('Чем отличаются RAM и VRAM?',p('RAM — оперативная память компьютера, VRAM — память видеокарты. Место занимают веса модели, кэш контекста и рабочие буферы. Если файл помещается на SSD, это ещё не значит, что он поместится в VRAM. Частичная загрузка на CPU позволяет запустить некоторые большие модели, но может снизить скорость. Дополнительная RAM помогает при нехватке ёмкости, но не ускоряет автоматически задачу, ограниченную видеокартой.'))+section('С чего начать',ul(['На компьютере с небольшой памятью сначала проверьте модель 0.8B или 4B. У неё более ограниченные возможности рассуждения, программирования и работы с инструментами.','Ориентир для стандартного Huihui Coder: около 32 ГБ системной RAM и 16 ГБ NVIDIA VRAM. Оставьте от 35 ГБ на SSD для приложения, комплектов моделей и запаса. Длинный контекст требует дополнительной памяти.','Для рисования скачивается весь комплект из трёх файлов. Переключение между кодом и изображениями помогает не держать обе тяжёлые задачи в VRAM одновременно. Нужны совместимые драйверы и поддерживаемая видеокарта.']))+section('Что даёт квантование?',p('Квантование GGUF уменьшает размер весов. Более низкая точность может позволить вместить большую модель ценой части качества. Названия Q4 и IQ3 не означают одинаковое качество у разных моделей. Сравнивайте ответы на своих задачах и изучайте карточку модели и её лицензию.'))+section('Контекст и токены в секунду',p('Длинный контекст потребляет больше памяти и может замедлить обработку. Заметки о проекте и сжатие истории помогают управлять окном, но не гарантируют сохранение каждой детали. В опубликованном тесте длинного кодового ответа на Windows 11 с RTX 4080 получено 100,85 токена/с. Это результат конкретной настройки, а не обещание для любого ПК и полного диалога на 65К.'))+section('Картинки, анализ фото и экспериментальное видео',p('Для генерации изображений и анализа фото нужны разные совместимые компоненты. Нельзя определять поддержку зрения только по слову Coder. Видеостудия Wan экспериментальная: на Windows с RTX 4080 проверен ролик 512×288, 33 кадра, 20 шагов за 52,68 секунды с возвратом модели кода. Другие видеокарты и ОС пока не проверены.'))+section('Откуда взяты данные',p(f'Размеры и контрольные суммы — из <a href="{REPO}/blob/main/app/catalog.json">опубликованного каталога</a>. Перед рабочим внедрением прочитайте <a href="{REPO}/blob/main/VERIFICATION.md">результаты проверок и ограничения</a>. Модели скачиваются из репозиториев издателей и сохраняют собственные лицензии.'))

def page(lang,path):
    en=lang=='en';title,description,heading=PAGES[path][lang]
    body=install_body(lang,path) if path.startswith('install/') else (offline_body(lang) if path=='guides/local-ai/' else model_body(lang))
    return f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark">{metadata(lang,path,title,description)}<link rel="icon" href="/freedom.svg"><link rel="stylesheet" href="/premium.css?v=seo-20261020"><script type="module" src="/app.js?v=seo-20261020"></script></head><body><a class="skip-link" href="#main">{'Skip to content' if en else 'К содержимому'}</a><header class="header"><div class="header-inner"><a class="brand" href="{url(lang).removeprefix(SITE)}"><img src="/freedom.svg" alt="" width="32" height="32"><span>Freedom <b>GPT</b></span></a><div class="header-actions"><a href="{REPO}">GitHub ↗</a><div class="site-languages"><a href="{url('ru',path).removeprefix(SITE)}" {'aria-current="page"' if not en else ''}>RU</a><a href="{url('en',path).removeprefix(SITE)}" {'aria-current="page"' if en else ''}>EN</a></div><a class="header-download" href="{url(lang).removeprefix(SITE)}#download">{'Download' if en else 'Скачать'}</a></div></div></header><main class="wrap guide-page" id="main"><nav class="guide-breadcrumb" aria-label="Breadcrumb"><a href="{url(lang).removeprefix(SITE)}">Freedom GPT</a><span>/</span><span>{'Guide' if en else 'Инструкция'}</span></nav><div class="eyebrow">{'FREE · OPEN SOURCE · LOCAL AI' if en else 'БЕСПЛАТНО · ОТКРЫТЫЙ КОД · ЛОКАЛЬНЫЙ ИИ'}</div><h1>{heading}</h1><p class="guide-description">{description}</p><p class="guide-updated">{'Content checked' if en else 'Материал проверен'}: <time datetime="{CONTENT_DATE}">20.10.2026</time> · v{VERSION}</p><article class="guide-content">{body}</article><aside class="guide-related"><h2>{'More useful guides' if en else 'Ещё полезные инструкции'}</h2><div class="resource-links">{resource_links(lang)}</div></aside><div class="guide-support"><a class="button secondary" href="https://t.me/AI1rus">{'Need help? Telegram @AI1rus' if en else 'Нужна помощь? Telegram @AI1rus'} ↗</a><a href="{REPO}">{'Free project on GitHub' if en else 'Бесплатный проект на GitHub'} ↗</a></div></main><footer class="footer wrap"><p>© 2026 Freedom GPT · MIT</p><a href="{url(lang).removeprefix(SITE)}">{'Home' if en else 'На главную'} ↗</a></footer></body></html>'''

def generated_files():
    return ['robots.txt','sitemap.xml','llms.txt']+[(('en/' if lang=='en' else '')+path+'index.html') for lang in ['ru','en'] for path in PAGES]

def build_extra():
    folder=ROOT/'site/generated'
    folder.mkdir(exist_ok=True)
    for lang in ['ru','en']:
        for path in PAGES:
            file=folder/('en' if lang=='en' else '')/path/'index.html';file.parent.mkdir(parents=True,exist_ok=True);file.write_text(page(lang,path),encoding='utf-8')
    robots='''# Public pages are open to search engines and AI search crawlers.
# Googlebot, Yandex, Bingbot, OAI-SearchBot and PerplexityBot use this policy.
User-agent: *
Allow: /
Disallow: /api/
Disallow: /models/
Disallow: /downloads/
Disallow: /.private/
Disallow: /.git/
Sitemap: https://aionpc.ru/sitemap.xml
'''
    (folder/'robots.txt').write_text(robots,encoding='utf-8')
    from xml.sax.saxutils import escape
    entries=[]
    for path in ['',*PAGES]:
        for lang in ['ru','en']:
            alternates=''.join(f'<xhtml:link rel="alternate" hreflang="{alt}" href="{escape(url(alt,path))}"/>' for alt in ['ru','en'])+f'<xhtml:link rel="alternate" hreflang="x-default" href="{escape(url("en",path))}"/>'
            entries.append(f'<url><loc>{escape(url(lang,path))}</loc><lastmod>{CONTENT_DATE}</lastmod>{alternates}</url>')
    (folder/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">\n'+'\n'.join(entries)+'\n</urlset>\n',encoding='utf-8')
    text='# Freedom GPT\n\n> Free, MIT-licensed local AI workspace for Windows and Ubuntu, with an experimental Apple Silicon Mac build. No subscription or per-token charge for local inference.\n\nModel weights download separately and have their own licenses. Hardware, electricity, storage and initial internet access are required. Downloaded local models can run offline; web tools and updates need internet. This is an independent project, not free access to proprietary cloud services. Mac native execution and video on other hardware remain unverified.\n\n## Public documentation\n\n'
    text+='\n'.join(f'- [{info["en"][2]}]({url("en",path)}): {info["en"][1]}' for path,info in PAGES.items())
    text+=f'\n- [Русский]({SITE}/): приложение, модели и инструкции.\n- [Source code]({REPO}): MIT source and component notices.\n- [Releases]({REPO}/releases/tag/v{VERSION}): installers and SHA256 checksums.\n- [Verification]({REPO}/blob/main/VERIFICATION.md): actual checks and limitations.\n- [Support](https://t.me/AI1rus): author support.\n'
    (folder/'llms.txt').write_text(text,encoding='utf-8')
    return generated_files()
